inlineStyles:
.privacy-page h1 { font-size: clamp(2rem, 7vw, 3.4rem); line-height: 1.05; margin: 0 0 16px; }
    .privacy-page h2 { font-size: clamp(1.35rem, 4vw, 1.8rem); line-height: 1.2; margin: 2.2rem 0 .75rem; }
    .privacy-page p, .privacy-page li { line-height: 1.75; }
    .privacy-page ul { padding-inline-start: 1.4rem; }
    .privacy-page a { color: #087f72; overflow-wrap: anywhere; }
    .privacy-toolbar { display:flex; align-items:center; justify-content:space-between; gap:20px; margin-bottom:32px; }
    .privacy-toolbar > a { margin:0 !important; }
    .privacy-language { display:flex; align-items:center; gap:10px; font-weight:700; }
    .privacy-language select { min-height:44px; max-width:220px; padding:0 36px 0 14px; border:1px solid rgba(23,60,63,.2); border-radius:999px; background:#fff; color:#173c3f; font:inherit; cursor:pointer; }
    .privacy-updated { font-weight:800; }
    @media (max-width:600px) { .privacy-toolbar { align-items:flex-start; flex-direction:column; } .privacy-language { width:100%; justify-content:space-between; } .privacy-language select { max-width:65%; } }

